package checkoutindex

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/sofired/berth/internal/checkoutindex/card"
	"github.com/sofired/berth/internal/registry"
)

// TestBuildSnapshotURLFilterOracle checks serviceBelongsToHost against
// internal/checkoutindex/testdata/url-filter.json, generated by
// tools/oracle/index-url-filter.ts from the real buildSnapshot: every WHATWG
// URL.parse normalization the TypeScript filter depends on — scheme and
// hostname case-folding, a default port dropped, a port's leading zeros, a
// trailing dot on the hostname, and an IPv6 literal. Regenerate with:
//
//	export PATH=$HOME/.local/opt/node-v24.14.1-linux-x64/bin:$PATH
//	node tools/oracle/index-url-filter.ts > internal/checkoutindex/testdata/url-filter.json
func TestBuildSnapshotURLFilterOracle(t *testing.T) {
	data, err := os.ReadFile("testdata/url-filter.json")
	if err != nil {
		t.Fatalf("reading oracle data: %v", err)
	}
	var oracle struct {
		Host  string `json:"host"`
		Cases []struct {
			Name       string `json:"name"`
			URL        string `json:"url"`
			RouterPort int    `json:"routerPort"`
			Kept       bool   `json:"kept"`
			KeptURL    string `json:"keptUrl"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(data, &oracle); err != nil {
		t.Fatalf("parsing oracle data: %v", err)
	}
	if len(oracle.Cases) == 0 {
		t.Fatal("empty oracle corpus; regenerate testdata/url-filter.json")
	}

	record := registry.RegisteredWorktree{RepositoryID: testRepo, WorktreeID: testWorktreeIDs[0], Slug: "feature-a", Domain: "acme.localhost"}

	for _, c := range oracle.Cases {
		t.Run(c.Name, func(t *testing.T) {
			input := SnapshotInput{
				Registrations: []registry.RegisteredWorktree{record},
				Cards: map[string]card.IndexCard{
					EntryKey(record.RepositoryID, record.WorktreeID): {
						Project: "acme", Domain: record.Domain, Slug: record.Slug, Host: oracle.Host,
						Root: "/work/feature-a", Branch: "feature/a", LabelNamespace: "dev.berth",
						Services:  []card.IndexService{{Name: "svc", URL: c.URL, Label: "Service", Purpose: ""}},
						UpdatedAt: "2026-01-01T00:00:00.000Z",
					},
				},
				RouterPort:  c.RouterPort,
				GeneratedAt: "2026-01-01T00:00:00.000Z",
			}
			entry := findBySlug(BuildSnapshot(input).Entries, record.Slug)
			if entry == nil {
				t.Fatal("registration not found in the snapshot")
			}
			kept := len(entry.Services) > 0
			if kept != c.Kept {
				t.Fatalf("kept = %v, want %v (url %q, routerPort %d)", kept, c.Kept, c.URL, c.RouterPort)
			}
			if kept && entry.Services[0].URL != c.KeptURL {
				t.Errorf("kept url = %q, want %q", entry.Services[0].URL, c.KeptURL)
			}
		})
	}
}
